func DecodeListKeysRequest(mux goahttp.Muxer, decoder func(*http.Request) goahttp.Decoder) func(*http.Request) (*jsonwebkeysets.ListKeysPayload, error) {
	return func(r *http.Request) (*jsonwebkeysets.ListKeysPayload, error) {
		var payload *jsonwebkeysets.ListKeysPayload
		var (
			setID          string
			includeRevoked bool
			sessionToken   *string
			err            error
		)
		qp := r.URL.Query()
		setID = qp.Get("set_id")
		if setID == "" {
			err = goa.MergeErrors(err, goa.MissingFieldError("set_id", "query string"))
		}
		err = goa.MergeErrors(err, goa.ValidateFormat("set_id", setID, goa.FormatUUID))
		{
			includeRevokedRaw := qp.Get("include_revoked")
			if includeRevokedRaw != "" {
				v, err2 := strconv.ParseBool(includeRevokedRaw)
				if err2 != nil {
					err = goa.MergeErrors(err, goa.InvalidFieldTypeError("include_revoked", includeRevokedRaw, "boolean"))
				}
				includeRevoked = v
			}
		}
		sessionTokenRaw := r.Header.Get("Gram-Session")
		if sessionTokenRaw != "" {
			sessionToken = &sessionTokenRaw
		}
		if err != nil {
			return payload, err
		}
		payload = NewListKeysPayload(setID, includeRevoked, sessionToken)
		if payload.SessionToken != nil {
			if strings.Contains(*payload.SessionToken, " ") {
				// Remove authorization scheme prefix (e.g. "Bearer")
				cred := strings.SplitN(*payload.SessionToken, " ", 2)[1]
				payload.SessionToken = &cred
			}
		}

		return payload, nil
	}
}

